import{_ as i,l,o as e,c as s,v as r,p as n,x as t,d,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"门限签名与 MPC 直觉","description":"","frontmatter":{"title":"门限签名与 MPC 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/threshold-mpc.md","filePath":"cs/threshold-mpc.md","lastUpdated":1789023840000}'),p={name:"cs/threshold-mpc.md"};function E(A,a,m,_,f,u){const o=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="门限签名与-mpc-直觉" tabindex="-1">门限签名与 MPC 直觉 <a class="header-anchor" href="#门限签名与-mpc-直觉" aria-label="Permalink to &quot;门限签名与 MPC 直觉&quot;">​</a></h1><div class="epigraph"><p>门限签名让 $t$ 方一起签发，任何一方拿不到完整私钥。安全多方计算把「一起算 $f$」当成协议目标，中间值按共享走，输出才打开。</p><footer>—— 据 Yao 百万富翁问题；Goldreich, Micali and Wigderson；对照 Boneh, Lynn and Shacham 对门限的后续工程</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/shamir-secret-sharing">Shamir</a>重构后秘密又聚回一点。缺口是<strong>计算阶段也不聚合明文</strong>。本课直觉：门限 ECDSA/EdDSA 与 MPC 的诚实多数/恶意模型，不写可部署的协议抄本。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HSM 是单盒；组织要「五人中三人签字」。门限：KeyGen 分布式，Sign 交互，Verify 仍用普通公钥。MPC：各方输入保密，只揭示 \\(f(x_1,\\ldots)\\)。缺口是目标陈述与敌手模型，不是电路乱码的实现作业。</p><h3 id="中止与公平" tabindex="-1">中止与公平 <a class="header-anchor" href="#中止与公平" aria-label="Permalink to &quot;中止与公平&quot;">​</a></h3><p>恶意敌手可让协议中止。公平性（要么都得输出要么都不得）更贵。工程上常退让。</p><p><span class="marginnote">Yao；GMW。DKLS 等门限 ECDSA 是工程文献，本课不点具体利用。后课同态是另一条「算密文」的路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对比三种：重构再签（弱）、门限签（私钥永不出现）、通用 MPC。写诚实多数 vs 恶意、带广播 vs 点对点。指出 nonce 在门限 ECDSA 里仍危险，EdDSA/Schnorr 更贴线性。</p>',12)),(e(),n(c,null,{default:t(()=>[h(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SH%5B%22%E4%BB%BD%E9%A2%9D%E7%95%99%E4%B8%8B%22%5D%20--%3E%20SIGN%5B%22%E4%BA%A4%E4%BA%92%E4%BA%A7%E7%94%9F%E7%AD%BE%E5%90%8D%22%5D%0A%20%20SIGN%20--%3E%20PUB%5B%22%E6%99%AE%E9%80%9A%E5%85%AC%E9%92%A5%E5%8F%AF%E9%AA%8C%22%5D%0A%20%20IN%5B%22%E7%A7%81%E6%9C%89%E8%BE%93%E5%85%A5%22%5D%20--%3E%20MPC%5B%22%E5%8D%8F%E8%AE%AE%E7%AE%97%20f%22%5D%0A%20%20MPC%20--%3E%20Y%5B%22%E5%8F%AA%E6%89%93%E5%BC%80%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最小特权：单人无法签。这服务治理，不服务「防所有侧信道」——交互本身有时序。网络异步下要小心同步假设。同态加密下一课把计算丢给持密文的一方，交互模式不同。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不提供门限 nonce 复用的攻击步骤。同态直觉下一课：密文上加乘，解密才见结果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>共享若重构再签，秘密又单点化。</li><li>门限签名：交互产出，公钥仍单把。</li><li>MPC 把任意 \\(f\\) 当协议；模型要写清恶意与中止。</li><li>下一课：同态加密直觉。</li><li>出处：Yao；Goldreich, Micali and Wigderson；Shamir, 1979。</li></ul>',8))])}const B=i(p,[["render",E]]);export{S as __pageData,B as default};
